 "content": "from collections import deque


def transform(grid):
    """Draw full lines from boundary 1 markers; recolor struck 2-objects."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == 1 and (r == 0 or r == h - 1 or c == 0 or c == w - 1)]
    rows = {r for r, _ in markers}
    cols = {c for _, c in markers}

    # Lines are painted across the entire grid, including over existing objects.
    for r in rows:
        for c in range(w):
            out[r][c] = 1
    for c in cols:
        for r in range(h):
            out[r][c] = 1

    # Any 4-connected 2-component touched by a marker line is recolored in full.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            touched = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                if y in rows or x in cols:
                    touched = True
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            if touched:
                for y, x in comp:
                    out[y][x] = 1
    return out

if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
